entries[90411] = { ["name"] = "Bodacious Door Knocker", ["text"] = "3 sec cast 5\nYou can only imagine what type of residence or business this artifact once adorned. This, er... knocker is in the shape of a buxom female dwarf with a gap-toothed smile, cheerfully bearing multiple pints.\nBodacious Door Knocker\nBinds when picked up" }
entries[90412] = { ["name"] = "Boot Heel with Scrollwork", ["text"] = "3 sec cast 5\nThe attention to detail in this simple boot heel suggests that the original piece of footwear might have been magical. The ornamentation is largely abstract, but you can make out small woodland animals- squirrels, deer, perhaps a skunk - hidden within all the scrollwork and stylized knots.\nBoot Heel with Scrollwork\nBinds when picked up" }
entries[90413] = { ["name"] = "Golden Chamber Pot", ["text"] = "3 sec cast 5\nApparently the rich and famous do all of their business in style. This piece is decorated with leaping fish and a running stream.\nGolden Chamber Pot\nBinds when picked up" }
entries[90414] = { ["name"] = "Despawn All Summons" }
entries[90415] = { ["name"] = "Winged Helm of Corehammer", ["text"] = "3 sec cast 5\nJudging from the size of this helm, Thane Corehammer of the Dark Irons must have been enormous, or possibly just enormously fat.\nWinged Helm of Corehammer\nBinds when picked up" }
entries[90416] = { ["name"] = "Eject Passenger All" }
