entries[90504] = { ["name"] = "Dented Shield of Horuz Killcrow", ["text"] = "3 sec cast 5\nThe grave mistake made by Horuz when he and his companions fought the great wyrm Kaldrigos cost the storied warrior his life. He stood directly behind the dragon. Never do that.\nDented Shield of Horuz Killcrow\nBinds when picked up" }
entries[90505] = { ["name"] = "Item - Shaman T11 Elemental 4P Bonus", ["text"] = "Reduces the cast time of your Lightning Bolt spell by 10%." }
entries[90506] = { ["name"] = "Scorched Staff of Shadow Priest Anund", ["text"] = "3 sec cast 5\nThis wooden staff has been thoroughly blackened by arcane breath. Such was the fate of its wielder as well.\nScorched Staff of Shadow Priest Anund\nBinds when picked up" }
entries[90507] = { ["name"] = "Death Eater", ["text"] = "Instant\nEach time you gain a Death Rune, you also gain 1% increased attack power for 30 sec. Stacks up to 3 times." }
entries[90508] = { ["name"] = "Burning Steppes Guardian Aura (H)" }
entries[90509] = { ["name"] = "Scepter of Charlga Razorflank", ["text"] = "3 sec cast 5\nAlthough these artifact fragments were found intermingled with those of dwarves, this scepter is clearly not of dwarven manufacture, but was made by quilboar. In fact, it was once wielded by Charlga Razorflank herself. Perhaps it came into dwarven possession when heroes attempted to conquer Razorfen Kraul.\nScepter of Charlga Razorflank\nBinds when picked up" }
entries[90510] = { ["name"] = "Quest Invisibility 25" }
entries[90511] = { ["name"] = "Invisibility Detection Quest 25" }
entries[90518] = { ["name"] = "Mithril Chain of Angerforge", ["text"] = "3 sec cast 5\nThe Angerforge family has a long lineage in Dark Iron dwarf history. This is a chain worn by Thane Angerforge, the ancestor of General Angerforge, who still commands the Dark Iron armies of Blackrock Depths.\nMithril Chain of Angerforge\nBinds when picked up" }
entries[90519] = { ["name"] = "Skull Staff of Shadowforge", ["text"] = "3 sec cast 5\nThe Shadowforge family has left a long stain on Dark Iron history. Iron Thane Shadowforge was by all accounts a cruel despot who tortured and killed many of his own people. While it is generally held that he was a warlock, some accounts cling to the rumor that he was one of the first dwarven shaman.\nSkull Staff of Shadowforge\nBinds when picked up" }
entries[90520] = { ["name"] = "Arcane Overload" }
entries[90521] = { ["name"] = "Clockwork Gnome", ["text"] = "3 sec cast 15\nMechagnomes were created by the titans, apparently as servants and caretakers, much like the earthen. This mechagnome was likely damaged because it is no longer focused on its original tasks and seems content to follow you.\nClockwork Gnome\nBinds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss your Clockwork Gnome." }
entries[90522] = { ["name"] = "Water Shell", ["text"] = "40 yd range\n2 sec cast\nAbsorbs 50000 damage, if the Water Shell is broken, it wil explode and inflict 48750 to 51250 Frost damage to enemies within 8 yards." }
