entries[90622] = { ["name"] = "Tiny Bronze Scorpion", ["text"] = "3 sec cast 5\nThis was apparently once an actual living scorpion which was dipped in bronze to preserve it. Scrawled on the bottom in Orcish: 'The chieftan laughs at your pathetic assassination attempts.'\nTiny Bronze Scorpion\nBinds when picked up" }
